function startRace(track,event,rivals){stopRace(false);const current=cars.find(c=>c.id===save.selected)||cars[0];race={track,event,rivals,mode,started:0,elapsed:0,progress:0,lane:0,speed:0,opponents:Array.from({length:rivals==='solo'?0:4},(_,i)=>({lane:[-.7,.45,-.35,.72][i],progress:rand(.03,.18),speed:rand(.083,.12),color:['#ff785f','#87a9f6','#e8c86d','#b68cef'][i],name:['MILO','ACE','KAI','NOVA'][i],passed:false})),car:current,boost:100,driftTime:0,tagTime:30,tagHolder:true,passes:0,trackIndex:trackNames.indexOf(track)};$('#raceMode').textContent=mode==='duel'?'GHOST DUEL':mode==='online'?'ONLINE RACE':mode==='event'?'TAG EVENT':'QUICK RACE';$('#raceMap').textContent=track.toUpperCase();$('#racePosition').innerHTML=`1<span>/${race.opponents.length+1}</span>`;$('#raceTimer').textContent='00:00.0';$('#speed').textContent='000';$('#speedBar').style.width='0%';$('#progressFill').style.width='0%';$('#finishPanel').classList.remove('show');$('#raceMessage').textContent=event==='bimba'?'YOU HAVE THE BIMBA · PASS IT BEFORE THE TIMER!':mode==='duel'?'GHOST DATA LOADED · BEAT YOUR BEST LINE':'';$('#raceToast').textContent='3';switchScreen('race');race.started=performance.now()+3200;race.last=performance.now();cancelAnimationFrame(animId);animId=requestAnimationFrame(gameLoop);let countdown=3;const countdownTimer=setInterval(()=>{if(!race){clearInterval(countdownTimer);return}countdown--;$('#raceToast').textContent=countdown>0?String(countdown):countdown===0?'GO!':'';if(countdown<0){clearInterval(countdownTimer);$('#raceToast').textContent=''}},800);keydownHandler=e=>{if(['ArrowLeft','a','A'].includes(e.key))controls.left=true;if(['ArrowRight','d','D'].includes(e.key))controls.right=true;if([' ','ArrowDown','Shift'].includes(e.key)){controls.drift=true;if(e.key===' ')e.preventDefault()}if(['ArrowUp','w','W'].includes(e.key))controls.boost=true};window.addEventListener('keydown',keydownHandler);window.addEventListener('keyup',e=>{if(['ArrowLeft','a','A'].includes(e.key))controls.left=false;if(['ArrowRight','d','D'].includes(e.key))controls.right=false;if([' ','ArrowDown','Shift'].includes(e.key))controls.drift=false;if(['ArrowUp','w','W'].includes(e.key))controls.boost=false},{once:false});}
function stopRace(goHome){if(!race)return;race=null;cancelAnimationFrame(animId);controls.left=controls.right=controls.drift=controls.boost=false;if(keydownHandler)window.removeEventListener('keydown',keydownHandler);$('#finishPanel').classList.remove('show');if(goHome)switchScreen('play')}
function gameLoop(now){if(!race)return;const dt=Math.min(.05,(now-race.last)/1000);race.last=now;const elapsed=now-race.started;const running=elapsed>0;const maxSpeed=(race.car.speed||62)/100*(controls.boost&&race.boost>0?1.32:1);race.speed+=(running?maxSpeed:0-race.speed)*Math.min(1,dt*2);if(!running)race.speed=Math.max(0,race.speed-dt*130);if(controls.left)race.lane-=dt*1.7;if(controls.right)race.lane+=dt*1.7;race.lane=Math.max(-1.25,Math.min(1.25,race.lane));if(controls.boost&&race.boost>0&&running)race.boost=Math.max(0,race.boost-dt*33);else race.boost=Math.min(100,race.boost+dt*11);if(controls.drift&&running){race.driftTime+=dt;race.progress+=dt*.008;save.tasks.drift=(save.tasks.drift||0)+dt;if(Math.random()<dt*.12)persist()}if(running){race.elapsed+=dt;let pace=.085*(race.speed/70);if(controls.boost&&race.boost>0)pace*=1.33;race.progress+=dt*pace;race.opponents.forEach(op=>{op.progress+=dt*op.speed;if(op.progress>=race.progress&&Math.abs(op.lane-race.lane)<.53){op.progress+=dt*.035;$('#raceMessage').textContent=`${op.name} IS TRYING TO PASS!`}else if(op.progress<race.progress-.1&&Math.random()<dt*.2){op.lane+=(Math.random()-.5)*.8}});let pos=1+race.opponents.filter(o=>o.progress>race.progress).length;$('#racePosition').innerHTML=`${pos}<span>/${race.opponents.length+1}</span>`;if(race.event==='bimba'){race.tagTime-=dt;if(race.tagTime<0){race.tagHolder=false;race.tagTime=rand(7,15);race.passes++;$('#raceMessage').textContent='BIMBA PASSED! +25 CREDITS';save.coins+=25;persist()}$('#raceMessage').textContent=race.tagHolder?`YOU HAVE THE BIMBA · ${Math.ceil(race.tagTime)}s`:`BIMBA IS WITH A RIVAL · ${Math.ceil(race.tagTime)}s`}
    if(race.progress>=1){finishRace(pos);return}}
